    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address player = address(0x1234);
        // Give player enough ether for two plays
        vm.deal(player, 100);

        // First winning play: random must be 0
        // To ensure random == 0, we set block.timestamp and block.difficulty such that
        // keccak256(abi.encodePacked(block.timestamp, block.difficulty, player)) % 2 == 0
        // We can try with block.timestamp = 1, block.difficulty = 1
        vm.warp(1);
        vm.roll(1); // sets block.difficulty to 1 via block.chainid? No, block.difficulty is separate
        // Actually block.difficulty cannot be set directly in Foundry, but we can use vm.difficulty
        vm.difficulty(1);
        vm.prank(player);
        c.play{value: 10}();

        // Second winning play, ensure random == 0 again with different timestamp/difficulty?
        // Since block.timestamp and block.difficulty are now 1 and 1, we need a different combination
        // to make random == 0 again. Let's use block.timestamp = 2, block.difficulty = 2
        vm.warp(2);
        vm.difficulty(2);
        vm.prank(player);
        c.play{value: 10}();

        // After two winning plays:
        // Reference: pot accumulates fee (1 wei per win) = 2 wei, but after first win pot becomes 1, then second win adds 10, then sends 10 - 1 = 9 to player, pot becomes 1 again => pot = 1
        // Buggy: after first win, pot becomes 0 (since sends pot = 10, including fee), then second win adds 10, sends pot = 10, pot becomes 0 => pot = 0
