    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deployer is bank, record initial bank balance
        address bank = address(this);
        uint bankInitial = bank.balance;

        // Manually set block.timestamp and block.difficulty to ensure random == 0
        // block.timestamp must be even? block.difficulty and msg.sender combine; we set them to make keccak256 result even
        vm.warp(1); // block.timestamp = 1
        vm.difficulty(2); // block.difficulty = 2
        // msg.sender (this contract) combined with these should produce an even hash
        // We can directly compute: keccak256(abi.encodePacked(1, 2, address(this))) % 2
        // If not 0, we adjust until it is
        // Let's find a block.timestamp that works
        // Actually simpler: we can rely on block.timestamp being variable; but we must guarantee random == 0
        // Precompute: we can try addresses, but we control msg.sender
        // We'll loop until we find a combination
        for (uint t = 1; t < 100; t++) {
            for (uint d = 1; d < 100; d++) {
                uint r = uint(keccak256(abi.encodePacked(t, d, address(this)))) % 2;
                if (r == 0) {
                    vm.warp(t);
                    vm.difficulty(d);
                    break;
                }
            }
            // Check if we found; break outer
            uint r = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, address(this)))) % 2;
            if (r == 0) break;
        }

        vm.deal(address(this), 10 ether);
        c.play{value: 10 ether}();

        // After winning call: reference (correct) sends 1 wei fee to bank, so bank balance increases by 1
        // Buggy sends 0 wei fee, bank balance unchanged
